def ch_items(a,b):
    labels = {1:'The Bet',2:'Digging',3:'Training Camp',4:'The First Worm',5:'The Gathering Storm',6:'The Second Worm',7:'Red Crash Helmets and White Jump Suits',8:'The Third Worm',9:'The Plotters',10:'The Fourth Worm',11:'Tom',12:'The Fifth Worm',13:'Nothing to Worry About',14:'The Pain and the Blood and the Gore',15:'3:15 A.M.',16:'The Sixth Worm',17:'The Seventh Worm',18:'The Eighth Worm',19:'The Ninth Worm',20:'Billy’s Mother',21:'The Tenth Worm',22:'The Eleventh Worm',23:'Admirals Nagumo and Kusaka on the Bridge of the Akaiga',24:'The Twelfth Worm',25:'Pearl Harbor',26:'Guadalcanal',27:'The Thirteenth Worm',28:'Hello, We’re….',29:'XXXIX',30:'The Peace Treaty',31:'The Letter',32:'Croak',33:'The Fourteenth Worm',34:'The Fifteenth….',35:'Burp',36:'The Fifteenth Wo….',37:'Out of the Frying Pan into the Oven',38:'$ % // ! ? Blip * / & !',39:'The United States Cavalry Rides over the Hilltop',40:'The Fifteenth Worm',41:'Epilogue'}
    return ''.join(f'<div class="item"><strong>Chapter {i} — {escape(labels.get(i, "Reading"))}</strong><span>读完这一小节后，在心里复述发生了什么，再勾选完成。</span></div>' for i in range(a,b+1))

def page(day, d):
    a,b=d['ch']; mins='';
    vocab=''.join(f'<div class="fc" onclick="this.classList.toggle(\'open\')"><b>{escape(w)}</b><em>点击翻卡</em><div class="cn">{escape(cn)}<br><small>{escape(ex)}</small></div></div>' for w,cn,ex in d['vocab'])
    tabs=''.join(f'<button class="{"active" if i==a else ""}" onclick="load({i},this)">Ch.{i}</button>' for i in range(a,b+1))
    qs=''.join(f'<div class="q" data-correct="{correct}"><p>{n}. {escape(q)}</p>'+''.join(f'<button class="opt" data-key="{k}" onclick="answer(this)">{k}. {escape(x)}</button>' for k,x in zip("ABCD",opts))+ '</div>' for n,(q,opts,correct) in enumerate(d['qs'],1))
    tags=''.join(f'<span class="tag">{escape(w)} · {escape(cn)}</span>' for w,cn in d['bank'])
    starters=''.join(f'<div>• {escape(s)}</div>' for s in d['starters'])
    return f'''<!doctype html><html lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Day {day} · How to Eat Fried Worms 共读营</title><meta name="description" content="How to Eat Fried Worms Day {day} 任务卡：逐章阅读、完整音频、阅读理解、单词和写作"><meta property="og:title" content="Day {day} · How to Eat Fried Worms 共读营"><meta property="og:description" content="逐章阅读 · 完整朗读音频 · 阅读理解 · 写作提交"><meta property="og:image" content="__OG_BASE__/fried-worms/og-image.jpg"><style>{CSS}</style></head><body><header class="hero"><div class="worm">🪱</div><div class="camp">HOW TO EAT FRIED WORMS · 英文共读营</div><div class="pill">Day {day} · 7 天共读</div><h1>{escape(d['title'])}</h1><div class="meta">Chapter {a}–{b} · 先读书，再听完整音频</div></header><div class="name">你的名字：<input id="studentName" placeholder="输入名字…" maxlength="20"></div><div class="quote">{escape(d['quote'])}</div><main class="content"><section class="card"><div class="head reading">📖 <div><b>今日阅读</b><small>Chapter {a}–{b} · 认真逐字逐句读完</small></div></div><div class="body"><p style="font-size:13px;line-height:1.6;margin-top:0">{escape(d['focus'])}</p>{ch_items(a,b)}<div class="tip">💡 阅读思考：{escape(d['tip'])}</div></div></section><section class="card"><div class="head audio">🎧 <div><b>朗读音频</b><small>American English · 每个小节都有对应音频</small></div></div><div class="body" style="background:#0f0c1d"><div class="player"><div class="tabs">{tabs}</div><div class="audio-title" id="audioTitle">Chapter {a}</div><audio id="audio" controls preload="metadata" src="audio/chapter{a:03d}.mp3"></audio><p style="font-size:11px;color:#ffffff88;text-align:center">建议：先看书逐字读，再用音频核对语音和语调。</p></div></div></section><section class="card"><div class="head quiz">🧠 <div><b>阅读理解</b><small>3 questions · 根据原文作答</small></div></div><div class="body">{qs}</div></section><section class="card"><div class="head vocab">🃏 <div><b>单词闪卡</b><small>6 words from today · 点击查看中文和例句</small></div></div><div class="body"><div class="flash">{vocab}</div></div></section><section class="card"><div class="head writing">✏️ <div><b>今日写作</b><small>英文写 3–5 句 · 拍照提交</small></div></div><div class="body"><div class="prompt"><b>Today’s Prompt</b><br>{escape(d['prompt'])}</div><div class="tags">{tags}</div><div class="starters"><b>Sentence Starters</b>{starters}</div><button class="submit" onclick="submitWork()">📷 拍照提交作业</button><div class="status" id="status"></div></div></section><section class="card"><div class="head teacher">💬 <div><b>助教的话</b><small>Day {day} 寄语</small></div></div><div class="body"><div class="teacherbox">{escape(d['note'])}<br><br>Remember: finish the book pages first, then use the audio to check your reading. You can do this! 📚</div></div></section></main><footer class="footer">How to Eat Fried Worms · 7-Day Reading Camp<br>认真读完每一个字，再写下你的想法。</footer><script>const chapterTitles={{}};function load(n,btn){{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const a=document.getElementById('audio');a.src='audio/chapter'+String(n).padStart(3,'0')+'.mp3';a.load();document.getElementById('audioTitle').textContent='Chapter '+n;}}function answer(btn){{const q=btn.closest('.q');if(q.classList.contains('done'))return;q.classList.add('done');const correct=q.dataset.correct;q.querySelectorAll('.opt').forEach(x=>{{if(x.dataset.key===correct)x.classList.add('correct')}});if(btn.dataset.key!==correct)btn.classList.add('wrong');}}function submitWork(){{const name=document.getElementById('studentName').value.trim();if(!name){{document.getElementById('status').textContent='请先输入名字，再提交作业。';return}}document.getElementById('status').textContent='请把纸上作业拍照后交给助教；今天的任务已完成！';}}</script></body></html>'''

for i,d in enumerate(days,1):
    (OUT/f'day{i}.html').write_text(page(i,d), encoding='utf-8')

copy = ['# How to Eat Fried Worms · 7天共读营助教每日群发文案', '', '> 使用说明：每天先发开营消息，提醒孩子按任务卡逐字读完当天章节，再听对应音频、完成理解题和英文写作。不要只听音频代替读书。', '']
